head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



scwin.onpageload = function () {
    // 사전 조건은 dataList 정적 데이터로 세팅됨 (추가 처리 없음)
};



// type 값별 CSV 업로드 (옵션은 type 하나만 지정)
scwin.btn_type0_onclick = function () {
    grd_type.readCSV({ type : "0" });
};

scwin.btn_type1_onclick = function () {
    grd_type.readCSV({ type : "1" });
};

scwin.btn_type2_onclick = function () {
    grd_type.readCSV({ type : "2" });
};



// 두 select Column 의 Cell 에 실제 렌더된 표시값을 Row 별로 출력
scwin.btn_getResult_onclick = function () {
    var nCnt = grd_type.getRowCount();
    var arrRow = [];

    for (var i = 0; i < nCnt; i++) {
        var objTdA = document.getElementById(grd_type.id + "_cell_" + i + "_1");
        var objTdB = document.getElementById(grd_type.id + "_cell_" + i + "_2");
        var strTextA = (objTdA === null) ? "" : (objTdA.textContent || "").trim();
        var strTextB = (objTdB === null) ? "" : (objTdB.textContent || "").trim();

        arrRow.push("[" + i + "] gradeA 표시=" + strTextA + " | gradeB 표시=" + strTextB);
    }

    scwin.setReturnValue("Row " + nCnt);
    for (var k = 0; k < arrRow.length; k++) {
        scwin.setReturnValue(arrRow[k]);
    }
};
